/**
 * Writes scripts/data/how-to-choose-healthcare-market-research-agency-saudi-arabia.json
 * with every Sanity blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by
 * scripts/generate-how-to-choose-healthcare-mr-agency-ksa-cover.mjs.
 *
 *   node scripts/generate-how-to-choose-healthcare-mr-agency-ksa-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(
  root,
  'scripts/data/how-to-choose-healthcare-market-research-agency-saudi-arabia.json',
);

export const IVONA_GUNJOVA_SANITY_ID = '5e67519a-1cdc-4b57-a881-29391db4accd';

/** Every blogPost field that applies to a healthcare-silo article. */
export const CHOOSE_AGENCY_KSA_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule(
      '/src/data/blog-how-to-choose-healthcare-market-research-agency-saudi-arabia.ts',
    );
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.CHOOSE_AGENCY_KSA_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.CHOOSE_AGENCY_KSA_BODY_HTML.split('<h2')[0])
    .replace(
      /^Choosing a healthcare market research agency in Saudi Arabia[\s\S]*?This checklist sits on our/,
      '',
    )
    .trim();

  return {
    seo: {
      metaTitle: mod.CHOOSE_AGENCY_KSA_META_TITLE,
      metaDescription: mod.CHOOSE_AGENCY_KSA_META_DESCRIPTION,
      focusKeyword: 'healthcare market research agency Saudi Arabia',
      keywords: [
        'healthcare market research agency Saudi Arabia',
        'how to choose a healthcare market research agency in Saudi Arabia',
        'healthcare market research agency in Saudi Arabia',
        'Saudi healthcare market research agency',
        'PDPL healthcare research Saudi Arabia',
        'NUPCO market research',
        'CHI healthcare research',
        'SFDA market research agency',
      ],
      canonicalUrl: mod.CHOOSE_AGENCY_KSA_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.CHOOSE_AGENCY_KSA_META_TITLE,
      ogDescription: mod.CHOOSE_AGENCY_KSA_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.CHOOSE_AGENCY_KSA_COVER_IMAGE}`,
        alt: mod.CHOOSE_AGENCY_KSA_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.CHOOSE_AGENCY_KSA_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.CHOOSE_AGENCY_KSA_SLUG },
    excerpt: mod.CHOOSE_AGENCY_KSA_EXCERPT,
    publishedAt: mod.CHOOSE_AGENCY_KSA_PUBLISHED_ISO,
    updatedAt: mod.CHOOSE_AGENCY_KSA_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: IVONA_GUNJOVA_SANITY_ID,
      name: 'Ivona Gunjova',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.CHOOSE_AGENCY_KSA_HERO_IMAGE}`,
      alt: mod.CHOOSE_AGENCY_KSA_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for choosing a healthcare market research agency in Saudi Arabia',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.CHOOSE_AGENCY_KSA_TAGS],
    country: 'Saudi Arabia',
    language: 'en',
    readingTime: mod.CHOOSE_AGENCY_KSA_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.CHOOSE_AGENCY_KSA_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.CHOOSE_AGENCY_KSA_EXECUTIVE_SUMMARY_HTML}\n\n${mod.CHOOSE_AGENCY_KSA_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: '10 questions to ask a healthcare market research agency in Saudi Arabia',
        type: 'table',
        data: JSON.stringify(
          mod.CHOOSE_AGENCY_KSA_QUESTIONS.map((question) => ({
            name: question.name,
            description: question.description,
          })),
        ),
        source: 'GASTAT 2023–2024; CHI 2025; PDPL; Vision 2030 Annual Report 2025; ICC/ESOMAR 2025',
      },
      portableText(
        firstParagraph ||
          'Choosing a healthcare market research agency in Saudi Arabia is a fieldwork and access problem before it is a brand-name problem.',
      ),
    ],
    faq: mod.CHOOSE_AGENCY_KSA_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: [
      'who-does-obesity-market-research-saudi-arabia',
      'glp-1-physician-survey-saudi-arabia',
      'hematology-market-research-saudi-arabia',
    ],
    ctaSection: { ...mod.CHOOSE_AGENCY_KSA_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.CHOOSE_AGENCY_KSA_BODY_HTML),
    factCheckedAt: mod.CHOOSE_AGENCY_KSA_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/how-to-choose-healthcare-market-research-agency-saudi-arabia-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of CHOOSE_AGENCY_KSA_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(
    `Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`,
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
